private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    try {
        while (bb.hasRemaining()) {
            int b = bb.get(i) & 0xFF;
            if ((b & 0x80) == 0) {
                // Single-byte character
                sb.append((char) b);
                i++;
            } else if ((b & 0xE0) == 0xC0) {
                // Two-byte character
                if (bb.remaining() < 2) break;
                int b2 = bb.get(i + 1) & 0xFF;
                sb.append((char) (((b & 0x1F) << 6) | (b2 & 0x3F)));
                i += 2;
            } else if ((b & 0xF0) == 0xE0) {
                // Three-byte character
                if (bb.remaining() < 3) break;
                int b2 = bb.get(i + 1) & 0xFF;
                int b3 = bb.get(i + 2) & 0xFF;
                sb.append((char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)));
                i += 3;
            } else if ((b & 0xF8) == 0xF0) {
                // Four-byte character
                if (bb.remaining() < 4) break;
                int b2 = bb.get(i + 1) & 0xFF;
                int b3 = bb.get(i + 2) & 0xFF;
                int b4 = bb.get(i + 3) & 0xFF;
                int codePoint = ((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F);
                sb.append(Character.toChars(codePoint));
                i += 4;
            } else {
                // Invalid UTF-8 sequence
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
        }
    } catch (IndexOutOfBoundsException e) {
        // Handle the case where the buffer is not large enough
        throw new IllegalArgumentException("ByteBuffer is not large enough to decode from index " + i);
    }
    return i;
}

