@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Graph and resultMap cannot be null");
    }

    Set<V> leftPartition = new HashSet<>();
    Set<V> rightPartition = new HashSet<>();

    // Assuming resultMap contains vertices with keys indicating their partition
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        if (entry.getKey().startsWith("left_")) {
            leftPartition.add(entry.getValue());
        } else if (entry.getKey().startsWith("right_")) {
            rightPartition.add(entry.getValue());
        } else {
            throw new IllegalArgumentException("Invalid key format in resultMap. Keys must start with 'left_' or 'right_'.");
        }
    }

    // Add vertices to the graph
    target.addAllVertices(leftPartition);
    target.addAllVertices(rightPartition);

    // Add edges between all vertices in the left partition and all vertices in the right partition
    for (V leftVertex : leftPartition) {
        for (V rightVertex : rightPartition) {
            target.addEdge(leftVertex, rightVertex);
        }
    }
}

