static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        // Extract year, month, and day from the timeBucket
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        // Calculate the new day by adjusting based on dayStep
        int newDay = ((day - 1) / dayStep) * dayStep + 1;

        // Return the new time bucket
        return year * 10000 + month * 100 + newDay;
    } catch (Exception e) {
        // Handle any unexpected exceptions
        throw new IllegalArgumentException("Invalid timeBucket or dayStep provided", e);
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Index and length must be non-negative and index + length must be less than or equal to the length of the string");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < index + len && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4; // surrogate pair
                i++; // skip the low surrogate
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair in string");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

