public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        int length = str.length();
        int index = 0;
        LinkedBuffer currentBuffer = lb;

        while (index < length) {
            int remaining = currentBuffer.limit - currentBuffer.offset;
            if (remaining == 0) {
                currentBuffer = currentBuffer.next = session.nextBuffer();
            }

            char c = str.charAt(index++);
            if (c < 0x80) {
                currentBuffer.buffer[currentBuffer.offset++] = (byte) c;
            } else if (c < 0x800) {
                currentBuffer.buffer[currentBuffer.offset++] = (byte) (0xc0 | (c >> 6));
                currentBuffer.buffer[currentBuffer.offset++] = (byte) (0x80 | (c & 0x3f));
            } else if (Character.isSurrogate(c)) {
                if (index >= length) {
                    throw new IllegalArgumentException("Invalid UTF-8 sequence");
                }
                char low = str.charAt(index++);
                if (!Character.isSurrogatePair(c, low)) {
                    throw new IllegalArgumentException("Invalid UTF-8 sequence");
                }
                int codePoint = Character.toCodePoint(c, low);
                currentBuffer.buffer[currentBuffer.offset++] = (byte) (0xf0 | (codePoint >> 18));
                currentBuffer.buffer[currentBuffer.offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
                currentBuffer.buffer[currentBuffer.offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
                currentBuffer.buffer[currentBuffer.offset++] = (byte) (0x80 | (codePoint & 0x3f));
            } else {
                currentBuffer.buffer[currentBuffer.offset++] = (byte) (0xe0 | (c >> 12));
                currentBuffer.buffer[currentBuffer.offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
                currentBuffer.buffer[currentBuffer.offset++] = (byte) (0x80 | (c & 0x3f));
            }
        }

        return lb;
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF-8 to LinkedBuffer", e);
    }
}

