    }
    int neededCapacity = (this.data == null ? 0 : this.data.length) + size;
    if (neededCapacity > (this.data == null ? 0 : this.data.length)) {
        int newCapacity = Math.max(neededCapacity, 2 * (this.data == null ? 0 : this.data.length));
        byte[] newData = new byte[newCapacity];
        if (this.data != null) {
