    try {
        for (K key : keys) {
            if (key instanceof Comparable) {
                @SuppressWarnings("unchecked")
                Comparable<K> comparableKey = (Comparable<K>) key;
                int lowerBound = findLowerBound(comparableKey, keys);
                lowerBounds.add(lowerBound);
