public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Normalize the paths by removing any trailing slashes
    path = path.endsWith("/") ? path.substring(0, path.length() - 1) : path;
    relativePath = relativePath.startsWith("/") ? relativePath.substring(1) : relativePath;

    // Split the relative path into parts
    String[] parts = relativePath.split("/");

    // Use a stack to build the final path
    Stack<String> pathStack = new Stack<>();
    for (String part : path.split("/")) {
        if (!part.isEmpty()) {
            pathStack.push(part);
        }
    }

    for (String part : parts) {
        if (part.equals("..")) {
            if (!pathStack.isEmpty()) {
                pathStack.pop();
            }
        } else if (!part.equals(".")) {
            pathStack.push(part);
        }
    }

    // Build the final path
    StringBuilder result = new StringBuilder();
    while (!pathStack.isEmpty()) {
        result.insert(0, pathStack.pop());
        if (!pathStack.isEmpty()) {
            result.insert(0, "/");
        }
    }

    return result.toString();
}

